// Native differential runner: optio (native CLI) vs HiGHS (highs-js) on the
// seeded LP/MIP suite generated by tools/gen-lp.mjs.
//
// For every manifest instance it:
//   1. solves with HiGHS to get the reference (status, objective, detached model,
//      solution) and independently checks the reference with `checkModel`;
//   2. serialises the *detached* model to a temp JSON file (infinities mapped to
//      +/-1e30, the native CLI's INF convention) and runs
//      `cargo run -q -p optio-bench -- --model-json <file> [--time] [--gap] [--lp]`;
//   3. independently verifies optio's `colValue` with `checkModel` — optio's own
//      status is never trusted;
//   4. compares status parity (with documented acceptable mappings), feasibility,
//      and objective within a relative tolerance.
//
// Usage:  node src/native.mjs
// Env:    ONLY=lp|mip        restrict to one instance kind
//         TIME_LIMIT=<secs>  override every instance's time limit
//         SKIP_GEN=1         do not (re)generate the suite first
//
// Writes harness/native-report.json.
import { readFileSync, writeFileSync, existsSync, mkdtempSync, rmSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { tmpdir } from 'node:os';
import { performance } from 'node:perf_hooks';

import { loadHighs, highsSource } from './highs.mjs';
import { checkModel, statusName } from './checker.mjs';
import { NO_SOLUTION_STATUSES } from './fixtures.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const harnessDir = join(here, '..');
const repoRoot = join(here, '..', '..');
const fixtureDir = join(harnessDir, 'fixtures', 'lp');
const manifestPath = join(fixtureDir, 'manifest.json');
const reportPath = join(harnessDir, 'native-report.json');

const ONLY = process.env.ONLY ?? null;
const TIME_LIMIT = Number(process.env.TIME_LIMIT ?? 0);
const SKIP_GEN = !!process.env.SKIP_GEN;

// Objective tolerance: relative delta |o - r| / max(1, |r|).
const OBJ_RTOL = 1e-4;

// Statuses that may carry a primal solution (mirrors optio_core has_feasible_solution).
const SOLUTION_STATUSES = new Set([
  'Optimal', 'TimeLimit', 'IterationLimit', 'ObjectiveBound',
  'ObjectiveTarget', 'SolutionLimit', 'Interrupt',
]);
const INFEASIBLE_CLASS = new Set(['Infeasible', 'UnboundedOrInfeasible']);
const UNBOUNDED_CLASS = new Set(['Unbounded', 'UnboundedOrInfeasible']);

/** Acceptable status pairs. `UnboundedOrInfeasible` is the ambiguous HiGHS bucket. */
function statusCompatible(ref, got) {
  if (ref === got) return true;
  if (INFEASIBLE_CLASS.has(ref) && INFEASIBLE_CLASS.has(got)) return true;
  if (UNBOUNDED_CLASS.has(ref) && UNBOUNDED_CLASS.has(got)) return true;
  return false;
}

// ---------------------------------------------------------------------------
// Formatting / serialisation helpers
// ---------------------------------------------------------------------------
const pad = (s, n) => String(s).padEnd(n);
const padL = (s, n) => String(s).padStart(n);
const num = (v, d = 0) => (Number.isFinite(v) ? v.toFixed(d) : String(v));
const INF = 1e30;

function asArray(a) {
  return a == null ? [] : Array.from(a);
}

/** Map a bound vector, converting +/-Infinity to the CLI's finite INF sentinel. */
function asBounds(a) {
  return asArray(a).map((x) => (Number.isFinite(x) ? x : x > 0 ? INF : x < 0 ? -INF : 0));
}

function asIntArray(a) {
  return asArray(a).map((x) => (Number.isFinite(x) ? Math.trunc(x) : 0));
}

/** Serialise a highs-js `getModel('csr')` detached model for the native CLI. */
function detachedToJson(d) {
  return {
    numCols: d.numCols,
    numRows: d.numRows,
    colCost: asArray(d.colCost),
    colLower: asBounds(d.colLower),
    colUpper: asBounds(d.colUpper),
    rowLower: asBounds(d.rowLower),
    rowUpper: asBounds(d.rowUpper),
    integrality: asIntArray(d.integrality),
    matrix: {
      format: 'csr',
      starts: asIntArray(d.matrix.starts),
      indices: asIntArray(d.matrix.indices),
      values: asArray(d.matrix.values),
    },
  };
}

// ---------------------------------------------------------------------------
// Solver drivers
// ---------------------------------------------------------------------------
async function runHighs(highs, lp, seconds) {
  const t0 = performance.now();
  const model = highs.createModel({ format: 'lp', data: lp });
  try {
    model.options.set({ output_flag: false, time_limit: seconds });
    model.run();
    const statusCode = model.getModelStatus();
    const status = statusName(statusCode);
    const detached = model.getModel('csr');
    const expectsSolution = !NO_SOLUTION_STATUSES.has(status);
    let colValue = null;
    if (expectsSolution) {
      try {
        colValue = Array.from(model.getSolution().colValue);
      } catch {
        colValue = null;
      }
    }
    let objective = null;
    try {
      objective = model.getObjectiveValue();
    } catch {
      objective = null;
    }
    const check = colValue ? checkModel(detached, colValue, 1e-6) : null;
    return { statusCode, status, detached, colValue, objective, check, ms: performance.now() - t0 };
  } finally {
    model.dispose?.();
  }
}

/** Run the native CLI; retries once on a transient failure (e.g. mid-refactor build). */
function runNative(jsonPath, { seconds, gap, lpOnly }) {
  const args = [
    'run', '-q', '--release', '-p', 'optio-bench', '--',
    '--model-json', jsonPath,
    '--time', String(seconds),
    '--gap', String(gap),
  ];
  if (lpOnly) args.push('--lp');

  let lastErr = null;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const out = execFileSync('cargo', args, {
        cwd: repoRoot,
        encoding: 'utf8',
        timeout: Math.max(30, seconds + 60) * 1000,
        maxBuffer: 256 * 1024 * 1024,
        stdio: ['ignore', 'pipe', 'pipe'],
        env: { ...process.env, CARGO_TERM_COLOR: 'never' },
      });
      const lines = out.split(/\r?\n/).filter((l) => l.trim().length > 0);
      const last = lines[lines.length - 1] ?? '';
      return { ok: true, json: JSON.parse(last), raw: out };
    } catch (err) {
      lastErr = err;
    }
  }
  return {
    ok: false,
    error: String(lastErr?.stderr || lastErr?.message || lastErr).trim(),
  };
}

// ---------------------------------------------------------------------------
// Driver
// ---------------------------------------------------------------------------
function ensureManifest() {
  if (SKIP_GEN) {
    if (!existsSync(manifestPath)) {
      throw new Error(`manifest missing and SKIP_GEN set: ${manifestPath} (run node tools/gen-lp.mjs)`);
    }
    return;
  }
  // Regenerate deterministically so the runner is self-contained.
  execFileSync(process.execPath, [join(here, '..', 'tools', 'gen-lp.mjs')], {
    cwd: repoRoot,
    stdio: 'ignore',
  });
}

async function main() {
  ensureManifest();
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
  let instances = manifest.instances ?? [];
  if (ONLY) instances = instances.filter((i) => i.kind === ONLY);

  const highs = await loadHighs();
  const work = mkdtempSync(join(tmpdir(), 'optio-native-'));
  const jsonPath = join(work, 'model.json');

  console.log(`highs-js:  ${highsSource}`);
  console.log(`optio CLI: cargo run -q --release -p optio-bench -- --model-json <tmp> (cwd ${repoRoot})`);
  console.log(`instances: ${instances.length}${ONLY ? ` (ONLY=${ONLY})` : ''}${TIME_LIMIT ? ` TIME_LIMIT=${TIME_LIMIT}` : ''}\n`);
  console.log(
    pad('instance', 18) + pad('kind', 5) + pad('hi-status', 15) + pad('optio-status', 15) +
    padL('hi-obj', 13) + padL('optio-obj', 13) + padL('rel-delta', 11) +
    pad('hiF', 4) + pad('optF', 5) + pad('st', 4) + pad('obj', 4) + padL('viol|ms', 9),
  );
  console.log('-'.repeat(124));

  const records = [];
  for (const inst of instances) {
    const filePath = join(fixtureDir, inst.file);
    if (!existsSync(filePath)) {
      console.log(pad(inst.name, 18) + 'MISSING ' + filePath);
      records.push({ ...inst, error: 'missing fixture' });
      continue;
    }
    const lp = readFileSync(filePath, 'utf8');
    const seconds = TIME_LIMIT > 0 ? TIME_LIMIT : inst.seconds;
    const lpOnly = inst.kind === 'lp';
    const gap = 1e-4;

    const rec = { name: inst.name, file: inst.file, kind: inst.kind, seconds, expect: inst.expect };

    try {
      const ref = await runHighs(highs, lp, seconds);
      rec.highs = {
        status: ref.status,
        statusCode: ref.statusCode,
        objective: ref.objective,
        feasible: ref.check ? ref.check.feasible : null,
        maxRowViolation: ref.check ? ref.check.maxRowViolation : null,
        ms: ref.ms,
      };

      writeFileSync(jsonPath, JSON.stringify(detachedToJson(ref.detached)));

      const t1 = performance.now();
      const nat = runNative(jsonPath, { seconds, gap, lpOnly });
      const nativeMs = performance.now() - t1;

      if (!nat.ok) {
        rec.optio = { error: nat.error };
        console.log(pad(inst.name, 18) + 'NATIVE-ERROR ' + nat.error.split('\n')[0]);
        records.push(rec);
        continue;
      }
      if (nat.json.error) {
        rec.optio = { error: nat.json.error };
        console.log(pad(inst.name, 18) + 'CLI-ERROR ' + nat.json.error);
        records.push(rec);
        continue;
      }

      const oStatus = statusName(nat.json.statusCode);
      const oObj = Number.isFinite(nat.json.objective) ? nat.json.objective : null;
      const oColValue = Array.isArray(nat.json.colValue) ? nat.json.colValue : null;

      const claimsSolution = SOLUTION_STATUSES.has(oStatus) && oColValue && oColValue.length >= ref.detached.numCols;
      const oCheck = claimsSolution ? checkModel(ref.detached, oColValue, 1e-6) : null;

      const statusMatch = statusCompatible(ref.status, oStatus);
      const bothObjectives = Number.isFinite(ref.objective) && Number.isFinite(oObj);
      const relDelta = bothObjectives
        ? Math.abs(oObj - ref.objective) / Math.max(1, Math.abs(ref.objective))
        : null;
      const objMatch = relDelta != null ? relDelta <= OBJ_RTOL : null;

      // A "bug" is: optio claims a solution but the independent checker rejects it.
      const feasibilityBug = claimsSolution && oCheck && !oCheck.feasible;

      rec.optio = {
        status: oStatus,
        statusCode: nat.json.statusCode,
        objective: oObj,
        nodes: nat.json.nodes,
        iterations: nat.json.iterations,
        ms: nativeMs,
        check: oCheck,
      };
      rec.compare = { statusMatch, bothObjectives, relDelta, objMatch, feasibilityBug };

      const maxViol = oCheck
        ? Math.max(oCheck.maxRowViolation, oCheck.maxBoundViolation, oCheck.maxIntegralityViolation)
        : null;
      const flags = [];
      if (!statusMatch) flags.push('STATUS');
      if (objMatch === false) flags.push('OBJ');
      if (feasibilityBug) flags.push('INFEASIBLE!');

      console.log(
        pad(inst.name, 18) + pad(inst.kind, 5) + pad(ref.status, 15) + pad(oStatus, 15) +
        padL(ref.objective == null ? 'n/a' : ref.objective.toFixed(4), 13) +
        padL(oObj == null ? 'n/a' : oObj.toFixed(4), 13) +
        padL(relDelta == null ? 'n/a' : relDelta.toExponential(2), 11) +
        pad(ref.check ? (ref.check.feasible ? 'yes' : 'NO') : 'n/a', 4) +
        pad(oCheck ? (oCheck.feasible ? 'yes' : 'NO') : (claimsSolution ? '?' : 'n/a'), 5) +
        pad(statusMatch ? 'ok' : 'X', 4) +
        pad(objMatch == null ? '-' : objMatch ? 'ok' : 'X', 4) +
        padL(num(maxViol == null ? nativeMs : maxViol, 1), 9) +
        (flags.length ? '  ' + flags.join(',') : ''),
      );

      records.push(rec);
    } catch (err) {
      rec.error = String(err?.message ?? err);
      console.log(pad(inst.name, 18) + 'ERROR ' + rec.error);
      records.push(rec);
    }
  }

  const summary = summarise(records);
  printSummary(summary, records);

  writeFileSync(
    reportPath,
    JSON.stringify(
      {
        highs: highsSource,
        generatedAt: new Date().toISOString(),
        objTolerance: OBJ_RTOL,
        summary,
        records,
      },
      null,
      2,
    ),
  );
  console.log(`\nwrote ${reportPath}`);

  rmSync(work, { recursive: true, force: true });
}

function summarise(records) {
  const ok = records.filter((r) => r.optio && !r.optio.error && r.compare);
  const lps = ok.filter((r) => r.kind === 'lp');
  const mips = ok.filter((r) => r.kind === 'mip');

  const lpMatched = lps.filter(
    (r) => r.compare.statusMatch && r.compare.objMatch !== false && !r.compare.feasibilityBug,
  ).length;
  // Feasible (non-special) LPs only: the spec's headline "match HiGHS" count.
  const lpsFeasible = lps.filter((r) => r.expect === 'feasible');
  const lpFeasibleMatched = lpsFeasible.filter(
    (r) => r.compare.statusMatch && r.compare.objMatch !== false && !r.compare.feasibilityBug,
  ).length;
  const lpsSpecial = lps.filter((r) => r.expect !== 'feasible');
  const lpSpecialMatched = lpsSpecial.filter((r) => r.compare.statusMatch).length;
  const mipFeasible = mips.filter(
    (r) => r.optio.check && r.optio.check.feasible,
  ).length;
  const mipOptimal = mips.filter((r) => r.optio.status === 'Optimal').length;

  return {
    total: records.length,
    errored: records.filter((r) => r.error || (r.optio && r.optio.error)).length,
    lp: {
      total: lps.length,
      matchedStatusAndObjective: lpMatched,
      feasibleTotal: lpsFeasible.length,
      feasibleMatched: lpFeasibleMatched,
      specialTotal: lpsSpecial.length,
      specialMatched: lpSpecialMatched,
      statusMismatch: lps.filter((r) => !r.compare.statusMatch).length,
      objectiveMismatch: lps.filter((r) => r.compare.objMatch === false).length,
      feasibilityBug: lps.filter((r) => r.compare.feasibilityBug).length,
    },
    mip: {
      total: mips.length,
      feasibleSolution: mipFeasible,
      optimal: mipOptimal,
      statusMismatch: mips.filter((r) => !r.compare.statusMatch).length,
      objectiveMismatch: mips.filter((r) => r.compare.objMatch === false).length,
      feasibilityBug: mips.filter((r) => r.compare.feasibilityBug).length,
    },
  };
}

function printSummary(s, records) {
  console.log('\n' + '='.repeat(60));
  console.log('SUMMARY');
  console.log('='.repeat(60));
  console.log(`instances: ${s.total}  (errors: ${s.errored})`);
  console.log(
    `LP : ${s.lp.matchedStatusAndObjective}/${s.lp.total} match HiGHS ` +
    `(status+objective<=${OBJ_RTOL}) ` +
    `[feasible ${s.lp.feasibleMatched}/${s.lp.feasibleTotal}, ` +
    `special ${s.lp.specialMatched}/${s.lp.specialTotal}]; ` +
    `status-mismatch=${s.lp.statusMismatch} obj-mismatch=${s.lp.objectiveMismatch} ` +
    `infeasible-solution=${s.lp.feasibilityBug}`,
  );
  console.log(
    `MIP: ${s.mip.feasibleSolution}/${s.mip.total} feasible (checker), ` +
    `${s.mip.optimal} optimal; status-mismatch=${s.mip.statusMismatch} ` +
    `obj-mismatch=${s.mip.objectiveMismatch} infeasible-solution=${s.mip.feasibilityBug}`,
  );

  const bad = records.filter(
    (r) =>
      r.error ||
      (r.optio && r.optio.error) ||
      (r.compare && (!r.compare.statusMatch || r.compare.objMatch === false || r.compare.feasibilityBug)),
  );
  if (bad.length) {
    console.log('\nDISCREPANCIES');
    for (const r of bad) {
      if (r.error || (r.optio && r.optio.error)) {
        console.log(`  - ${r.name}: ERROR ${r.error ?? r.optio.error}`);
        continue;
      }
      const c = r.compare;
      const ref = r.highs;
      const o = r.optio;
      const parts = [];
      if (!c.statusMatch) parts.push(`status ${ref.status} -> ${o.status}`);
      if (c.objMatch === false) {
        parts.push(`obj ${ref.objective} -> ${o.objective} (rel ${c.relDelta.toExponential(2)})`);
      }
      if (c.feasibilityBug) {
        parts.push(
          `checker REJECTS claimed solution (rowViol=${o.check.maxRowViolation.toExponential(2)}, ` +
          `boundViol=${o.check.maxBoundViolation.toExponential(2)}, intViol=${o.check.maxIntegralityViolation.toExponential(2)})`,
        );
      }
      console.log(`  - ${r.name} [${r.kind}]: ${parts.join('; ')}`);
    }
  } else {
    console.log('\nNo discrepancies.');
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
